static void combiSR(LinkedList<Integer>L1,
                    LinkedList<Integer>L2,
                    int r,int i){

    if(L1.size()==r){
        System.out.println(L1);
        return;
    }

    for(int k=i;k<L2.size();k++){
        L1.add(L2.get(k));
        combiSR(L1,L2,r,k+1);
        L1.removeLast();
    }
}
